				ps.hasTornSeq = true
			}
			break
		}
		seq := binary.LittleEndian.Uint64(data[off+4 : off+12])
		count := binary.LittleEndian.Uint32(data[off+12 : off+16])
		pos := off + entryHeaderLen
		records := make([][]byte, 0, min(int(count), 1<<20))
