func TestConcurrentReadAndScan(t *testing.T) {
    l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
    const batches = 50
    var wg sync.WaitGroup
    // single writer
    wg.Add(1)
    go func() {
        defer wg.Done()
        for i := 1; i <= batches; i++ {
            b, err := l.Append([][]byte{[]byte(fmt.Sprintf("rec-%d", i))})
            if err != nil { t.Errorf(...); return }
            if _, err := l.Commit(b); err != nil { t.Errorf(...); return }
        }
    }()
    // readers
    for g := 0; g < 3; g++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            for i := 0; i < 200; i++ {
                seq := uint64(i%batches + 1)
                got, err := l.Read(seq)
                switch {
                case errors.Is(err, log.ErrNotCommitted), errors.Is(err, log.ErrUnknownBatch):
                case err != nil: t.Errorf("Read: %v", err); return
                default:
                    want := fmt.Sprintf("rec-%d", seq)
                    if len(got) != 1 || string(got[0]) != want { t.Errorf(...); return }
                }
                // mutating the result must not affect later reads
                if len(got) == 1 && len(got[0]) > 0 { got[0][0] = 'X' }
            }
        }()
    }
